D={
70063:("Números grandes","**Hundred, thousand, million.** *Two hundred, three thousand.* Sem -s depois de número: **two hundred**, não *two hundreds*.",[("{{One hundred}} guests.","Cem convidados."),("{{Two thousand}} dollars.","Dois mil dólares."),("A party for {{fifty}} people.","Uma festa para cinquenta pessoas."),("You're invited!","Você está convidado!")],"“Duzentos”:",["two hundred","two hundreds","hundred two"],0,"Sem -s depois de número."),
10173:("Superlativo: the -est","Para o maior grau: **the + adjetivo curto + -est**. *tall → the tallest, old → the oldest.* Exceção: **good → the best**.",[("He is {{the tallest}}.","Ele é o mais alto."),("This is {{the oldest}} house.","Esta é a casa mais antiga."),("It's {{the smallest}} room.","É o menor quarto."),("She is {{the best}} player.","Ela é a melhor jogadora.")],"Superlativo de good:",["the goodest","the best","the most good"],1,"Irregular: the best."),
70065:("Números ordinais","**First, second, third, fourth, fifth.** Do 4º em diante, quase sempre **-th**. Na escrita: 1st, 2nd, 3rd, 4th.",[("My {{first}} day.","Meu primeiro dia."),("The {{second}} floor.","O segundo andar."),("The {{third}} week.","A terceira semana."),("The {{fifth}} of May.","O cinco de maio.")],"“Terceiro”:",["third","threeth","thirth"],0,"Irregular: third."),
30033:("Pedir ajuda: Call…","Em emergência: **Call 911! Call the police!** Diga o problema: **There is an accident.** Peça: **Help me, please!**",[("{{Call}} the police!","Chame a polícia!"),("There is {{an accident}}.","Há um acidente."),("We need an ambulance.","Precisamos de uma ambulância."),("{{Help}}, please!","Ajuda, por favor!")],"O que dizer em emergência?",["Call the police!","Please a cup.","Good morning."],0,"Imperativo: Call…"),
70066:("Ordinais 7 a 10","**Seventh, eighth, ninth, tenth.** Cuidado: *eight → eighth* (só -h), *nine → ninth* (perde o e).",[("My {{seventh}} file.","Meu sétimo arquivo."),("The {{eighth}} key.","A oitava tecla."),("The {{ninth}} page.","A nona página."),("The {{tenth}} cable.","O décimo cabo.")],"Ordinal de nine:",["ninth","nineth","ninnth"],0,"nine → ninth."),
910016:("Look at, look for","**Look at** = olhar para. **Look for** = procurar. **Look up** = buscar (dicionário). *I look for my keys.*",[("{{Look at}} this poster.","Olhe este cartaz."),("I {{look for}} my keys.","Procuro minhas chaves."),("{{Look up}} the word.","Procure a palavra."),("Did you find it?","Você encontrou?")],"“Procurar”:",["look for","look at","look up"],0,"Look for = procurar."),
10174:("Hora cheia e meia","**It's three o'clock** (hora cheia). **It's half past three** (três e meia). **It's quarter past** (e quinze).",[("{{It's three o'clock}}.","São três em ponto."),("{{It's half past three}}.","São três e meia."),("{{It's quarter past four}}.","São quatro e quinze."),("The parade starts at six.","O desfile começa às seis.")],"“Cinco e meia”:",["half past five","five past half","half five past"],0,"half past + hora."),
70067:("Ferramentas: use / need","Para pedir ferramentas: **I need a hammer. Can I use the ladder?** *Need* = precisar.",[("I {{need}} a hammer.","Preciso de um martelo."),("{{Can I use}} the ladder?","Posso usar a escada?"),("Fix the fence.","Conserte a cerca."),("The nails are in the shed.","Os pregos estão no galpão.")],"“Preciso de um prego”:",["I need a nail.","I need nail a.","I do need nail."],0,"need + a/an."),
30034:("Presente simples","Para fatos e rotinas: **It rains a lot. I stay home.** Com he/she/it: verbo + **-s**: *It rains. She stays.*",[("It {{rains}} in spring.","Chove na primavera."),("We {{stay}} home.","Ficamos em casa."),("Thunder {{scares}} the dog.","O trovão assusta o cachorro."),("The fog {{is}} thick.","A neblina é espessa.")],"Complete: “It ___ a lot.”",["rain","rains","raining"],1,"it + verbo-s."),
70068:("Presente simples: -s","Terceira pessoa: **+s** (*she takes*) ou **+es** com -s, -sh, -ch, -x, -o (*she watches, he goes*).",[("She {{takes}} the pill.","Ela toma o comprimido."),("He {{coughs}} a lot.","Ele tosse muito."),("The nurse {{watches}} him.","A enfermeira o observa."),("He {{goes}} to bed early.","Ele vai cedo para a cama.")],"Complete: “She ___ TV.” (watch)",["watch","watches","watchs"],1,"watch → watches."),
10175:("Quinze minutos","**Quarter past** = e quinze. **Quarter to** = quinze para. *It's quarter to six* = 5:45.",[("It's {{quarter past}} three.","São três e quinze."),("It's {{quarter to}} four.","Faltam quinze para as quatro."),("The spider is small.","A aranha é pequena."),("The frog jumps.","O sapo pula.")],"3:45 é…",["quarter to four","quarter past three","half past four"],0,"Quarter to four."),
70069:("Quinze minutos","*Quarter* = um quarto de hora. **Past** = depois. **To** = para. *Quarter past eight, quarter to nine.*",[("It's {{quarter past}} eight.","São oito e quinze."),("It's {{quarter to}} nine.","Faltam quinze para as nove."),("The owl sleeps at day.","A coruja dorme de dia."),("The fox runs fast.","A raposa corre rápido.")],"“Quinze para as dez”:",["quarter to ten","quarter past ten","ten quarter"],0,"Quarter to ten."),
30035:("Minutos: past e to","**Past** vai até meia hora; **to** depois. *Ten past two. Twenty to three.*",[("It's {{ten past}} two.","São duas e dez."),("It's {{twenty to}} three.","Faltam vinte para as três."),("The whale is huge.","A baleia é enorme."),("A crab lives by the shell.","Um caranguejo vive perto da concha.")],"2:50 é…",["ten to three","ten past two","two to ten"],0,"Até meia hora: past; depois: to."),
70070:("Minutos: past e to","*Five past, ten past, twenty past* até 30; *twenty-five to, ten to, five to* depois de 30.",[("It's {{five past}} one.","É uma e cinco."),("It's {{ten to}} two.","Faltam dez para as duas."),("The rent is high.","O aluguel é alto."),("The attic is dusty.","O sótão é empoeirado.")],"“Cinco para as três”:",["five to three","five past three","three to five"],0,"Five to three."),
910017:("First, next, then, finally","Para passos: **First** (primeiro), **next** (depois), **then** (então), **finally** (por fim). Cada um ocupa o começo da frase.",[("{{First}}, mix the flour.","Primeiro, misture a farinha."),("{{Next}}, add the eggs.","Depois, adicione os ovos."),("{{Then}}, stir.","Então, mexa."),("{{Finally}}, bake it.","Por fim, asse.")],"Qual palavra abre a receita?",["First","Finally","Then"],0,"First = primeiro."),
10176:("Meses: in + mês","Meses usam **in**: **in January, in March**. *My interview is in March.* Dia exato usa **on**: *on March 5th.*",[("My interview is {{in}} March.","Minha entrevista é em março."),("The deadline is {{in}} June.","O prazo é em junho."),("It's {{on}} June 5th.","É no dia 5 de junho."),("My colleague starts in May.","Meu colega começa em maio.")],"Qual preposição com meses?",["on","in","at"],1,"in + mês."),
70071:("In + mês, in + ano","**In** vale para meses, anos, estações: *in May, in 2020, in summer.* Para um dia: **on**.",[("The gallery opens {{in}} May.","A galeria abre em maio."),("It's from {{in}} 2020.","É de 2020."),("A novel {{in}} winter.","Um romance no inverno."),("The exhibit is on Friday.","A exposição é na sexta.")],"“Em 2020”:",["in 2020","on 2020","at 2020"],0,"in + ano."),
30036:("In + estação","Estações pedem **in**: *in summer, in autumn.* *We rake the leaves in autumn.*",[("We rake leaves {{in autumn}}.","Rastelamos folhas no outono."),("The harvest is {{in September}}.","A colheita é em setembro."),("I shiver {{in winter}}.","Eu tremo no inverno."),("It's hot in August.","Faz calor em agosto.")],"Com estações, use…",["in","on","at"],0,"in + estação."),
70072:("In + estação","Estações e meses: **in October, in winter**. Cuidado: *at night*, mas *in the morning*.",[("It's cold {{in}} December.","Faz frio em dezembro."),("We decorate {{in}} winter.","Decoramos no inverno."),("It's dark {{at}} night.","Fica escuro à noite."),("I see you {{in}} the morning.","Vejo você de manhã.")],"“À noite”:",["at night","in night","on night"],0,"at night."),
10177:("A data completa","Data: **It's May 5th.** Falamos *May fifth*. **On** + dia: *on May 5th*. Ano: **in 2024**.",[("{{It's}} May 5th.","É 5 de maio."),("My anniversary is {{on}} May 5th.","Meu aniversário de casamento é 5 de maio."),("The holiday is in July.","O feriado é em julho."),("What's today's date?","Qual é a data de hoje?")],"“No dia 5 de maio”:",["on May 5th","in May 5th","at May 5th"],0,"on + data."),
70073:("Décadas e séculos","**Decade** = década; **century** = século. *In the 1990s. In the 21st century.* Parada: *parade*.",[("It is {{a decade}} old.","Tem uma década."),("A {{century}} is 100 years.","Um século são cem anos."),("In {{the 1990s}}.","Nos anos 1990."),("The parade starts at noon.","O desfile começa ao meio-dia.")],"Quantos anos tem um século?",["100","10","1000"],0,"Century = 100."),
30037:("On + dia","Dias: **on Tuesday, on Wednesday, on Thursday**. Para repetição: **on Tuesdays** (toda terça).",[("I rest {{on Tuesday}}.","Descanso na terça."),("We study {{on Wednesdays}}.","Estudamos às quartas."),("What day is it today?","Que dia é hoje?"),("It's Thursday.","É quinta.")],"“Às terças” (sempre):",["on Tuesdays","in Tuesday","at Tuesdays"],0,"on + dia(s)."),
70074:("Fim de semana","**At the weekend** (UK) ou **on the weekend** (US). **Weekday** = dia útil. *Saturday is my day off.*",[("{{Saturday}} is my day off.","Sábado é minha folga."),("I rest {{on the weekend}}.","Descanso no fim de semana."),("Weekdays are busy.","Os dias úteis são cheios."),("I recharge on Sunday.","Recarrego as energias no domingo.")],"“Dia útil”:",["weekday","weekend","holiday"],0,"Weekday."),
910018:("Awesome! Cool! Great!","Para aprovar: **Awesome! Cool! Great! Amazing!** *That's awesome!* Em respostas curtas, uma só palavra serve.",[("{{Awesome}}!","Demais!"),("That's {{cool}}.","Que legal."),("{{Great}} job!","Ótimo trabalho!"),("You're so {{lucky}}!","Que sorte a sua!")],"Resposta animada:",["Awesome!","Sorry.","Please."],0,"Awesome = demais."),
10178:("Dólares e centavos","**Dollars** e **cents**: *two dollars and fifty cents*. Moedas: **penny** (1¢), **nickel** (5¢), **dime** (10¢).",[("{{Two dollars}} and {{fifty cents}}.","Dois dólares e cinquenta centavos."),("A {{penny}} is one cent.","Um penny é um centavo."),("A {{dime}} is ten cents.","Uma moeda de dime vale dez centavos."),("I have a budget.","Tenho um orçamento.")],"Um nickel vale…",["5 centavos","10 centavos","1 centavo"],0,"Nickel = 5¢."),
70075:("Preço e imposto","**Tax** = imposto. **Price + tax**. *It's ten dollars plus tax.* *That's a bargain!* = pechincha.",[("It's ten dollars {{plus tax}}.","São dez dólares mais imposto."),("{{That's a bargain}}!","É uma pechincha!"),("I have change in my pocket.","Tenho trocados no bolso."),("Keep the change.","Fique com o troco.")],"O que é bargain?",["pechincha","imposto","troco"],0,"Bargain = pechincha."),
10179:("I'd like…","Para pedir: **I'd like** + algo. *I'd like some groceries.* Mais gentil que *I want*.",[("{{I'd like}} some dairy.","Gostaria de alguns laticínios."),("{{I'd like}} fresh produce.","Gostaria de produtos frescos."),("Can I sample it?","Posso experimentar?"),("Thank you!","Obrigado!")],"Mais educado:",["I'd like milk.","Give milk.","I want milk."],0,"I'd like."),
70077:("Paper or plastic?","No caixa: **Paper or plastic?** = sacola de papel ou plástico? Respostas: **Paper, please.** *Do you have a bag?*",[("{{Paper or plastic}}?","Papel ou plástico?"),("{{Paper}}, please.","Papel, por favor."),("{{Next customer}}, please.","Próximo cliente, por favor."),("Here is your receipt.","Aqui está o seu recibo.")],"“Papel, por favor” significa…",["sacola de papel","sacola de plástico","sem sacola"],0,"Paper = papel."),
30039:("Can I…?","Para pedir permissão: **Can I pay by card?** Resposta: **Yes, you can. / Sorry, you can't.**",[("{{Can I}} pay by card?","Posso pagar com cartão?"),("Yes, {{you can}}.","Sim, pode."),("{{Can I}} cancel my subscription?","Posso cancelar minha assinatura?"),("Sorry, {{you can't}}.","Desculpe, não pode.")],"Como pedir permissão para pagar com cartão?",["Can I pay by card?","I can card?","Can pay I card?"],0,"Can I + verbo."),
70078:("Can I / May I","**May I** é ainda mais formal que **Can I**: *May I see your signature?* Resposta: **Of course.**",[("{{May I}} see your ID?","Posso ver seu documento?"),("{{Can I}} sign here?","Posso assinar aqui?"),("{{Of course}}.","Claro."),("Sign here, please.","Assine aqui, por favor.")],"Mais formal:",["May I","Can I","Do I"],0,"May I é mais formal."),
}
